import numpy as np,json
p='/app/runs/current_obs/'
D=np.load(p+'last_depth_wrist_cam.npy');m=json.load(open(p+'meta.json'));E=np.array(m['cameras']['wrist_cam']['extrinsic_cv']);R=E[:,:3];t=E[:,3];K=np.array([[666.6667,0,640],[0,666.6667,360],[0,0,1.]])
def proj(w):
 c=R@np.array(w)+t;return (K@c)[:2]/c[2],c
for name,w in [('tcp',m['proprio']['now'][8:11]),('remote', [.27,-.13,.026]),('mouse',[.334,-.308,.04])]:print(name,proj(w))
def back(u,v,r=2):
 z=D[v-r:v+r+1,u-r:u+r+1];z=z[z>0];d=np.median(z);c=np.array([(u-640)/666.6667*d,(v-360)/666.6667*d,d]);return np.round(R.T@(c-t),4),float(d)
for pt in [(695,300),(690,380),(670,410),(680,420),(705,230),(1000,330),(350,420)]:print(pt,back(*pt))
